package com.fream.back.domain.payment.entity;

public enum PaymentCategory {

    SHOPPING("쇼핑 관련 알림"),
    STYLE("스타일 관련 알림");

    private final String description;

    PaymentCategory(String description) {
        this.description = description;
    }

    public String getDescription() {
        return description;
    }
}package com.fream.back.domain.payment.entity;

public enum PaymentType {


    TRADE(PaymentCategory.SHOPPING, "거래 관련 알림"),
    BID(PaymentCategory.SHOPPING, "입찰 관련 알림"),
    STORAGE(PaymentCategory.SHOPPING, "보관 관련 알림"),
    FAVORITE(PaymentCategory.SHOPPING, "관심 상품 관련 알림"),
    BENEFIT(PaymentCategory.SHOPPING, "혜택 관련 알림"),
    ANNOUNCEMENT(PaymentCategory.SHOPPING, "공지사항 알림"),
    REFUND(PaymentCategory.SHOPPING, "환불 관련 알림"),


    LIKE(PaymentCategory.STYLE, "좋아요 관련 알림"),
    COMMENT(PaymentCategory.STYLE, "댓글 관련 알림"),
    FOLLOW(PaymentCategory.STYLE, "팔로우 관련 알림");

    private final PaymentCategory category;
    private final String description;

    PaymentType(PaymentCategory category, String description) {
        this.category = category;
        this.description = description;
    }

    public PaymentCategory getCategory() {
        return category;
    }

    public String getDescription() {
        return description;
    }







    public static PaymentType[] getTypesByCategory(PaymentCategory category) {
        if (category == null) {
            return values();
        }

        return java.util.Arrays.stream(values())
                .filter(type -> type.getCategory() == category)
                .toArray(PaymentType[]::new);
    }
}

